BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 172" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="600">名前空間が分ける「見える範囲」</text><rect x="20" y="32" width="100" height="40" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="70.0" y="49" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="600">PID</text><text x="70.0" y="62" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">専用のプロセスID</text><rect x="130" y="32" width="100" height="40" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="180.0" y="49" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="600">NET</text><text x="180.0" y="62" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">専用のIP・ポート</text><rect x="240" y="32" width="100" height="40" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="290.0" y="49" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="600">MNT</text><text x="290.0" y="62" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">専用のファイルの木</text><rect x="20" y="82" width="100" height="40" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="70.0" y="99" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="600">UTS</text><text x="70.0" y="112" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">専用のホスト名</text><rect x="130" y="82" width="100" height="40" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="180.0" y="99" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="600">IPC</text><text x="180.0" y="112" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">専用のプロセス間通信</text><rect x="240" y="82" width="100" height="40" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="290.0" y="99" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="600">USER</text><text x="290.0" y="112" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">専用のユーザーID</text><text x="170" y="158" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">この6種の「見える範囲」を分けるのが名前空間。cgroupsは範囲でなく量を絞る（別物）</text></svg>')
WHERE q.source_ref = 'dca-q64'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 178" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="600">--privileged は「壁」をほぼ全部外す</text><text x="85" y="30" font-size="8.5" fill="#6ab08d" text-anchor="middle" font-weight="600">ふつうのコンテナ</text><rect x="20" y="40" width="130" height="18" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="85" y="52.5" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">capability: 最小限だけ</text><rect x="20" y="64" width="130" height="18" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="85" y="76.5" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">seccomp: 危険な操作を拒否</text><rect x="20" y="88" width="130" height="18" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="85" y="100.5" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">デバイス: ホストに触れない</text><text x="255" y="30" font-size="8.5" fill="#c47070" text-anchor="middle" font-weight="600">--privileged</text><rect x="190" y="40" width="130" height="18" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="255" y="52.5" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">capability: 全部付与</text><rect x="190" y="64" width="130" height="18" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="255" y="76.5" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">seccomp: フィルタなし</text><rect x="190" y="88" width="130" height="18" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="255" y="100.5" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">デバイス: ホストに直接触れる</text><text x="170" y="130" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">壁が無いので、コンテナの中からホストのカーネルを</text><text x="170" y="143" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">直接操作でき、ホストごと乗っ取られる経路になる</text></svg>')
WHERE q.source_ref = 'dca-q69'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 168" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9" fill="#e8eaf0" text-anchor="middle" font-weight="600">capability は権限の部品。要る分だけ足す</text><rect x="20" y="30" width="90" height="26" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="65" y="44" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">rootの全権限</text><text x="65" y="55" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">(約40種)</text><line x1="110" y1="43" x2="135" y2="43" stroke="#8892a4" stroke-width="1.2"/><rect x="135" y="30" width="90" height="26" rx="4" fill="#2a2416" stroke="#c9a04a" stroke-width="1"/><text x="180" y="44" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Docker既定</text><text x="180" y="55" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">(約14種に絞済)</text><line x1="225" y1="43" x2="250" y2="43" stroke="#8892a4" stroke-width="1.2"/><rect x="250" y="30" width="75" height="26" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="287.5" y="44" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">--cap-drop ALL</text><text x="287.5" y="55" font-size="6" fill="#e8eaf0" text-anchor="middle" font-weight="normal">--cap-add NET_BIND</text><text x="170" y="90" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">例: 80番ポートを使いたいだけなら</text><text x="170" y="103" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">全部いったん外して(--cap-drop ALL)、</text><text x="170" y="116" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">NET_BIND_SERVICE だけ足す(--cap-add)</text><text x="170" y="138" font-size="8" fill="#c9a04a" text-anchor="middle" font-weight="normal">余計な力を持たせないほど、乗っ取られたときの被害が小さい</text></svg>')
WHERE q.source_ref = 'dca-q24'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

