SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 158" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="8.7" fill="#e8eaf0" text-anchor="middle" font-weight="600">secret はディスクに書かず、メモリ上だけに渡す</text><rect x="15" y="30" width="100" height="30" rx="4" fill="#1a1e29" stroke="#3b82f6" stroke-width="1"/><text x="65" y="44" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">マネージャー</text><text x="65" y="56" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">暗号化して保管</text><line x1="115" y1="45" x2="145" y2="45" stroke="#c9a04a" stroke-width="1.3"/><rect x="145" y="30" width="180" height="30" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="235" y="44" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">コンテナ内 /run/secrets/</text><text x="235" y="56" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">tmpfs（メモリ上）にだけ置く</text><rect x="60" y="76" width="220" height="22" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="170" y="90" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">ディスクに書かれない＝盗まれにくい</text><text x="170" y="118" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">config（docker config）は平文でよい設定値、</text><text x="170" y="131" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">secret はパスワード等の機密値、という使い分け</text></svg>')
WHERE q.source_ref = 'dca-q67'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

COMMIT;